89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
100	     *  separated by '@', none of which contain whitespace or a second '@'. */
101	    private static final java.util.regex.Pattern EMAIL_PATTERN =
102	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
103	
104	    /**
105	     * Normalize the optional email: absent stays absent; when present it must be syntactically
106	     * valid and is lower-cased. Returns {@code false} if present but invalid.
107	     */
108	    private boolean normalizeEmail(Owner owner) {
109	        String email = owner.getEmail();
110	        if (email == null || email.isEmpty()) {
111	            owner.setEmail(null);
112	            return true;
113	        }
114	        if (!EMAIL_PATTERN.matcher(email).matches()) {
115	            return false;
116	        }
117	        owner.setEmail(email.toLowerCase(java.util.Locale.ROOT));
118	        return true;
119	    }
120	
121	    /**
122	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
123	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
124	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
125	     *
126	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
127	     *         a valid E.164 number.
128	     */
129	    private static String toE164(String raw) {
130	        if (raw == null) {
131	            return null;
132	        }
133	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
134	        String digits;
135	        if (cleaned.startsWith("+")) {
136	            digits = cleaned.substring(1);
137	        } else {
138	            if (cleaned.startsWith("0")) {
139	                cleaned = cleaned.substring(1);
140	            }
141	            digits = "61" + cleaned;
142	        }
143	        if (!digits.matches("\\d{8,15}")) {
144	            return null;
145	        }
146	        return "+" + digits;
147	    }
148	
149	    /**
150	     * Build the customer code {@code <CITY3>-<LAST3>-<NNNN>}: CITY3 is the upper-cased first three
151	     * letters of the city, LAST3 the upper-cased first three letters of the last name and NNNN a
152	     * per-city 4-digit zero-padded sequence equal to one more than the owners already in that city
153	     * (e.g. {@code SYD-SMI-0007}).
154	     */
155	    private String nextCustomerCode(String city, String lastName) {
156	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
157	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
158	        int sequence = 1;
159	        for (Owner existing : this.clinicService.findAllOwners()) {
160	            if (city.equalsIgnoreCase(existing.getCity())) {
161	                sequence++;
162	            }
163	        }
164	        return String.format("%s-%s-%04d", city3, last3, sequence);
165	    }
166	
167	    /** Common street-type abbreviations expanded during address normalization. */
168	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
169	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
170	
171	    /**
172	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
173	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
174	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
175	     */
176	    private static String normalizeAddress(String value) {
177	        if (value == null) {
178	            return "";
179	        }
180	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
181	        if (collapsed.isEmpty()) {
182	            return "";
183	        }
184	        String[] tokens = collapsed.split(" ");
185	        StringBuilder sb = new StringBuilder(collapsed.length());
186	        for (int i = 0; i < tokens.length; i++) {
187	            if (i > 0) {
188	                sb.append(' ');
189	            }
190	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
191	        }
192	        return sb.toString();
193	    }
194	
195	    /**
196	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
197	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
198	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
199	     */
200	    private static String normalizeForHousehold(String value) {
201	        if (value == null) {
202	            return "";
203	        }
204	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
205	    }
206	
207	    /**
208	     * Return the owners that already share this owner's household, i.e. have the same last name and
209	     * address compared case-insensitively with collapsed whitespace.
210	     */
211	    private List<Owner> householdMembers(Owner owner) {
212	        String lastName = normalizeForHousehold(owner.getLastName());
213	        String address = normalizeForHousehold(owner.getAddress());
214	        List<Owner> members = new java.util.ArrayList<>();
215	        for (Owner existing : this.clinicService.findAllOwners()) {
216	            if (normalizeForHousehold(existing.getLastName()).equals(lastName)
217	                && normalizeForHousehold(existing.getAddress()).equals(address)) {
218	                members.add(existing);
219	            }
220	        }
221	        return members;
222	    }
223	
224	    /**
225	     * Return {@code true} when another owner already shares this owner's household, i.e. has the same
226	     * last name and address compared case-insensitively with collapsed whitespace.
227	     */
228	    private boolean sharesHouseholdWithExisting(Owner owner) {
229	        return !householdMembers(owner).isEmpty();
230	    }
231	
232	    /**
233	     * Count the existing owners that share this owner's first name and last name, compared
234	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
235	     */
236	    private int namesakeCount(Owner owner) {
237	        String firstName = owner.getFirstName();
238	        String lastName = owner.getLastName();
239	        int count = 0;
240	        for (Owner existing : this.clinicService.findAllOwners()) {
241	            if (firstName != null && lastName != null
242	                && firstName.equalsIgnoreCase(existing.getFirstName())
243	                && lastName.equalsIgnoreCase(existing.getLastName())) {
244	                count++;
245	            }
246	        }
247	        return count;
248	    }
249	
250	    /**
251	     * A stable, shared household identifier derived from the normalized last name and address, so every
252	     * owner in the same household deterministically resolves to the same value.
253	     */
254	    private static String householdIdFor(Owner owner) {
255	        String key = normalizeForHousehold(owner.getLastName()) + "|" + normalizeForHousehold(owner.getAddress());
256	        try {
257	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
258	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
259	            StringBuilder sb = new StringBuilder(24);
260	            for (int i = 0; i < 12; i++) {
261	                sb.append(String.format("%02X", digest[i]));
262	            }
263	            return sb.toString();
264	        }
265	        catch (java.security.NoSuchAlgorithmException e) {
266	            throw new IllegalStateException(e);
267	        }
268	    }
269	
270	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
271	    @Override
272	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
273	        HttpHeaders headers = new HttpHeaders();
274	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
275	        String telephone = toE164(owner.getTelephone());
276	        if (telephone == null) {
277	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
278	        }
279	        if (!normalizeEmail(owner)) {
280	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
281	        }
282	        String address = normalizeAddress(owner.getAddress());
283	        if (address.isEmpty()) {
284	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
285	        }
286	        owner.setAddress(address);
287	        for (Owner existing : this.clinicService.findAllOwners()) {
288	            String existingTelephone = toE164(existing.getTelephone());
289	            if (telephone.equals(existingTelephone)) {
290	                return new ResponseEntity<>(HttpStatus.CONFLICT);
291	            }
292	        }
293	        List<Owner> householdMembers = householdMembers(owner);
294	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
295	        if (!sharesHousehold && !householdMembers.isEmpty()) {
296	            return new ResponseEntity<>(HttpStatus.CONFLICT);
297	        }
298	        if (sharesHousehold && !householdMembers.isEmpty()) {
299	            String householdId = householdMembers.stream()
300	                .map(Owner::getHouseholdId)
301	                .filter(id -> id != null && !id.isBlank())
302	                .findFirst()
303	                .orElseGet(() -> householdIdFor(owner));
304	            owner.setHouseholdId(householdId);
305	            for (Owner member : householdMembers) {
306	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
307	                    member.setHouseholdId(householdId);
308	                    this.clinicService.saveOwner(member);
309	                }
310	            }
311	        }
312	        owner.setNamesakeCount(namesakeCount(owner));
313	        owner.setTelephone(telephone);
314	        if (owner.getRegistrationDate() == null) {
315	            owner.setRegistrationDate(java.time.LocalDate.now());
316	        }
317	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
318	        this.clinicService.saveOwner(owner);
319	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
320	        headers.setLocation(UriComponentsBuilder.newInstance()
321	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
322	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
323	    }
324	
325	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
326	    @Override
327	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
328	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
329	        if (currentOwner == null) {
330	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
331	        }
332	        currentOwner.setAddress(ownerFieldsDto.getAddress());
333	        currentOwner.setCity(ownerFieldsDto.getCity());
334	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
335	        currentOwner.setLastName(ownerFieldsDto.getLastName());
336	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
337	        currentOwner.setEmail(ownerFieldsDto.getEmail());
338	        if (!normalizeEmail(currentOwner)) {
339	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
340	        }
341	        this.clinicService.saveOwner(currentOwner);
342	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
343	    }
344	
345	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
346	    @Transactional
347	    @Override
348	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
349	        Owner owner = this.clinicService.findOwnerById(ownerId);
350	        if (owner == null) {
351	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
352	        }
353	        this.clinicService.deleteOwner(owner);
354	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
355	    }
356	
357	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
358	    @Override
359	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
360	        Owner owner = this.clinicService.findOwnerById(ownerId);
361	        if (owner == null) {
362	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
363	        }
364	        HttpHeaders headers = new HttpHeaders();
365	        Pet pet = petMapper.toPet(petFieldsDto);
366	        owner.setId(ownerId);
367	        pet.setOwner(owner);
368	        pet.getType().setName(null);
369	        this.clinicService.savePet(pet);
370	        PetDto petDto = petMapper.toPetDto(pet);
371	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
372	            .buildAndExpand(pet.getId()).toUri());
373	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
374	    }
375	
376	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
377	    @Override
378	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
379	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
380	        if (currentOwner != null) {
381	            Pet currentPet = this.clinicService.findPetById(petId);
382	            if (currentPet != null) {
383	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
384	                currentPet.setName(petFieldsDto.getName());
385	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
386	                this.clinicService.savePet(currentPet);
387	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
388	            }
389	        }
390	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
391	    }
392	
393	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
394	    @Override
395	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
396	        HttpHeaders headers = new HttpHeaders();
397	        Visit visit = visitMapper.toVisit(visitFieldsDto);
398	        Pet pet = new Pet();
399	        pet.setId(petId);
400	        visit.setPet(pet);
401	        this.clinicService.saveVisit(visit);
402	        VisitDto visitDto = visitMapper.toVisitDto(visit);
403	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
404	            .buildAndExpand(visit.getId()).toUri());
405	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
406	    }
407	
408	
409	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
410	    @Override
411	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
412	        Owner owner = this.clinicService.findOwnerById(ownerId);
413	        if (owner != null) {
414	            Pet pet = owner.getPet(petId);
415	            if (pet != null) {
416	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
417	            }
418	        }
419	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
420	    }
421	}
